reversal.fixed_text:
let mut start = 0;
for (i, r) in escapes {
    v.extend_from_slice(&raw[start..i]);
    v.extend_from_slice(r);
    start = i + 1;
}

reversal.parent_text:
let mut start = 0;

for (i, r) in escapes {
    v.extend_from_slice(&raw[start..i]);
    start += i + 1;
    v.extend_from_slice(r);
}
